(function(){
  'use strict';
  const $=id=>document.getElementById(id),num=id=>Number($(id).value);
  function line(canvas,series,color,dash=[]){const x=canvas.getContext('2d'),w=canvas.width,h=canvas.height;x.save();x.strokeStyle=color;x.lineWidth=2;x.setLineDash(dash);x.beginPath();series.forEach((p,i)=>{const X=42+p[0]*(w-66),Y=h-28-p[1]*(h-52);i?x.lineTo(X,Y):x.moveTo(X,Y);});x.stroke();x.restore();}
  function clear(canvas){const x=canvas.getContext('2d');x.clearRect(0,0,canvas.width,canvas.height);x.fillStyle='#faf9f4';x.fillRect(0,0,canvas.width,canvas.height);x.strokeStyle='#bbb8ae';x.strokeRect(.5,.5,canvas.width-1,canvas.height-1);return x;}
  function bind(ids,fn){ids.forEach(id=>$(id).addEventListener('input',fn));fn();}
  function equivalence(){const n=Math.round(num('modulus')),root=$('class-grid');$('modulus-out').textContent=n;root.innerHTML='';for(let i=0;i<60;i++){const cell=document.createElement('span');cell.className='class-cell';cell.textContent=i;cell.title=`${i} ≡ ${i%n} (mod ${n})`;cell.style.background=`hsl(${(i%n)*360/n} 52% ${document.documentElement.matches('[data-dark]')?35:76}%)`;root.appendChild(cell);}$('class-readout').textContent=`60 integers collapse into ${n} equivalence classes; each class preserves only the remainder.`;}
  bind(['modulus'],equivalence);
  function recurrence(){const canvas=$('recurrence-canvas'),x=clear(canvas),r=num('r'),x0=num('x0'),delta=num('delta'),steps=Math.round(num('steps'));let a=x0,b=Math.min(.999999,x0+delta),first=-1;const A=[],B=[];for(let i=0;i<=steps;i++){A.push([i/steps,a]);B.push([i/steps,b]);if(first<0&&Math.abs(a-b)>.1)first=i;a=r*a*(1-a);b=r*b*(1-b);}line(canvas,A,'#12130f');line(canvas,B,'#9d392e',[6,4]);x.fillStyle='#12130f';x.font='12px ui-monospace,monospace';x.fillText('black: x₀   red dashed: x₀+Δ',48,19);$('r-out').textContent=r.toFixed(3);$('x0-out').textContent=x0.toFixed(3);$('delta-out').textContent=delta.toExponential(1);$('steps-out').textContent=steps;$('recurrence-readout').textContent=`First |Δₙ| > 0.1: ${first<0?'not reached':first}. This finite plot is an experiment, not a chaos proof.`;}
  bind(['r','x0','delta','steps'],recurrence);
  function pseudo(i){const z=Math.sin(i*12.9898+78.233)*43758.5453;return(z-Math.floor(z))*2-1;}
  function coarse(){const canvas=$('coarse-canvas'),x=clear(canvas),k=Math.round(num('grain')),noise=num('noise'),N=240,raw=[];for(let i=0;i<N;i++){const t=i/(N-1);raw.push(Math.max(0,Math.min(1,.5+.23*Math.sin(4*Math.PI*t)+.1*Math.sin(1.3*Math.PI*t)+noise*.18*pseudo(i))));}const avg=[];for(let start=0;start<N;start+=k){const end=Math.min(N,start+k),m=raw.slice(start,end).reduce((a,b)=>a+b,0)/(end-start);for(let j=start;j<end;j++)avg.push(m);}line(canvas,raw.map((v,i)=>[i/(N-1),v]),'#8f8c83',[2,3]);line(canvas,avg.map((v,i)=>[i/(N-1),v]),'#12130f');const mse=raw.reduce((sum,v,i)=>sum+(v-avg[i])**2,0)/N;x.fillStyle='#12130f';x.font='12px ui-monospace,monospace';x.fillText('gray dashed: fine   black: coarse',48,19);$('grain-out').textContent=k;$('noise-out').textContent=noise.toFixed(2);$('coarse-readout').textContent=`About ${Math.ceil(N/k)} macro-values remain from ${N}; discarded-detail MSE ${mse.toFixed(5)}.`;}
  bind(['grain','noise'],coarse);
  function landscape(t){return .11+.31*Math.exp(-(((t-.21)/.09)**2))+.7*Math.exp(-(((t-.73)/.115)**2))+.06*Math.sin(19*t);}
  function rng(seed){let state=seed>>>0;return()=>{state=(1664525*state+1013904223)>>>0;return state/4294967296;};}
  function optimize(){const canvas=$('opt-canvas'),x=clear(canvas),random=rng(Math.round(num('seed'))),amp=num('explore');let p=num('start');const track=[[p,landscape(p)]];for(let t=0;t<80;t++){const e=.006,grad=(landscape(Math.min(1,p+e))-landscape(Math.max(0,p-e)))/(2*e),candidate=Math.max(0,Math.min(1,p+.012*Math.sign(grad)+(random()-.5)*2*amp*(1-t/100)));if(landscape(candidate)>=landscape(p)||random()<.07+amp*.8)p=candidate;track.push([p,landscape(p)]);}const curve=[];for(let i=0;i<=500;i++){const t=i/500;curve.push([t,landscape(t)]);}line(canvas,curve,'#12130f');line(canvas,track.map(point=>[point[0],point[1]/1.05]),'#9d392e',[5,3]);const end=track.at(-1);x.fillStyle='#12130f';x.font='12px ui-monospace,monospace';x.fillText('black: landscape   red: search path',48,19);$('start-out').textContent=num('start').toFixed(3);$('explore-out').textContent=amp.toFixed(3);$('seed-out').textContent=Math.round(num('seed'));$('opt-readout').textContent=`Final x=${end[0].toFixed(3)}; objective=${end[1].toFixed(3)}. Change the seed: exploration can help or hurt.`;}
  bind(['start','explore','seed'],optimize);
  function collatz(){let n=Math.max(1,Math.round(num('collatz-start'))),steps=0,max=n;const seen=[],limit=250;while(steps<limit){seen.push(n);if(n===1)break;n=n%2===0?n/2:3*n+1;max=Math.max(max,n);steps++;}const root=$('orbit');root.innerHTML=seen.slice(0,90).map(value=>`<span class="${value%2?'odd':'even'}">${value}</span>`).join('')+(seen.length>90?'<span>…</span>':'');$('collatz-out').textContent=Math.round(num('collatz-start'));$('collatz-readout').textContent=`${steps} steps to ${n===1?'1':'the display limit'}; peak ${max.toLocaleString()}. Finite testing cannot settle the universal conjecture.`;}
  bind(['collatz-start'],collatz);
})();
